head.script:
scwin.onpageload = function () {
    // Fusionchart 'cht_exam1'의 초기 속성을 설정합니다.
    // 1. radio에 선택된 text를 차트의 caption으로 지정.
    // 2. 차트 캔버스의 상단 여백 지정.
    cht_exam1.setChartAttribute({
        "caption" : rad_chartType1.getText(),
        "canvasTopPadding" : 6
    });

    // 지정한 속성을 바탕으로 브라우저에 그립니다.
    cht_exam1.draw();
};

scwin.rad_chartType1_onviewchange = function (info) {
    // Fusionchart 'cht_exam1'의 속성을 설정합니다.
    // radio에 선택된 text를 차트의 caption으로 지정.
    cht_exam1.setChartAttribute({
        "caption" : rad_chartType1.getText()
    });

    // Fusionchart 'cht_exam1'의 차트 타입을 변경합니다.
    cht_exam1.changeType(info.value);
};

	scwin.checkVal1 = function() {
		var chartType2Elem = document.getElementsByClassName('raphael-group-379-plot-group')[0] || document.getElementsByClassName('raphael-group-381-plot-group')[0];
		return chartType2Elem.children[1].getAttribute('fill') == '#b5a1dd';
	}		
	scwin.checkVal2 = function() {
		var chartType2Elem = document.getElementsByClassName('raphael-group-379-plot-group')[0] || document.getElementsByClassName('raphael-group-381-plot-group')[0];
		return chartType2Elem.children[2].getAttribute('fill') == '#5ab0ee';
	}			
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('rad_chartType1_input_4').click()");
		WebSquare.wUnit.addCommand("pause", "700");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('rad_chartType1_input_2').click()");
		WebSquare.wUnit.addCommand("pause", "700");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('rad_chartType1_input_4').click()");
		WebSquare.wUnit.addCommand("pause", "1000");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");	
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
